1	package retention
2	
3	import (
4		"encoding/json"
5		"errors"
6		"os"
7		"path/filepath"
8		"strings"
9		"testing"
10	)
11	
12	func writeStateFile(t *testing.T, dir, content string) {
13		t.Helper()
14		if err := os.WriteFile(filepath.Join(dir, stateFileName), []byte(content), 0o600); err != nil {
15			t.Fatal(err)
16		}
17	}
18	
19	func readStateFile(t *testing.T, dir string) string {
20		t.Helper()
21		b, err := os.ReadFile(filepath.Join(dir, stateFileName))
22		if err != nil {
23			t.Fatal(err)
24		}
25		return string(b)
26	}
27	
28	// 已存在的状态文件内容不完整或不合法时，Open 必须明确失败，
29	// 调用者能借此区分“尚未建立记录”和“记录文件已经损坏”，且原文件保持原样。
30	func TestOpenRejectsCorruptStateFile(t *testing.T) {
31		corrupt := map[string]string{
32			"零字节文件":      "",
33			"只有空白":       "  \n\t \n",
34			"内容为 null":   "null",
35			"null 带空白":   " \n null \n",
36			"对象后拼接第二个值":  `{"version":1,"archives":{},"manifests":{}} {"version":1}`,
37			"对象后拼接 null": `{"version":1,"archives":{},"manifests":{}} null`,
38			"对象后夹非法文字":   `{"version":1,"archives":{},"manifests":{}} 这不是合法JSON`,
39			"半截 JSON":    `{"version":1,"archives":{`,
40			"顶层不是对象":     `[{"version":1}]`,
41		}
42		for name, content := range corrupt {
43			t.Run(name, func(t *testing.T) {
44				dir := t.TempDir()
45				writeStateFile(t, dir, content)
46	
47				s, err := Open(dir)
48				if err == nil {
49					s.Close()
50					t.Fatalf("损坏内容 %q 不应打开成功", content)
51				}
52				if !errors.Is(err, ErrCorruptState) {
53					t.Fatalf("错误应可判定为 ErrCorruptState，得到 %v", err)
54				}
55				if got := readStateFile(t, dir); got != content {
56					t.Fatalf("打开失败后原文件被改动: %q -> %q", content, got)
57				}
58			})
59		}
60	}
61	
62	// 状态文件不存在时按空库打开，可以正常登记。
63	func TestOpenMissingStateFileOpensEmptyStore(t *testing.T) {
64		dir := t.TempDir()
65		s, err := Open(dir)
66		if err != nil {
67			t.Fatalf("状态文件不存在时应能打开空库: %v", err)
68		}
69		defer s.Close()
70		reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
71		if _, found, err := s.History("A-1"); err != nil || !found {
72			t.Fatalf("登记后应能查询: found=%v err=%v", found, err)
73		}
74	}
75	
76	// 正常保存的空库对象（没有档案或清册）仍然有效；对象前后允许空白。
77	func TestOpenAcceptsEmptyStoreObjectWithWhitespace(t *testing.T) {
78		dir := t.TempDir()
79		writeStateFile(t, dir, " \n {\"version\":1,\"archives\":{},\"manifests\":{}} \n\n")
80	
81		s, err := Open(dir)
82		if err != nil {
83			t.Fatalf("空库对象应能打开: %v", err)
84		}
85		defer s.Close()
86		reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
87	}
88	
89	// 保管库打开后文件才损坏：下一次查询与办理都必须明确失败，
90	// 不能给出正常结论，也不能改动原文件。
91	func TestCorruptionAfterOpenFailsSubsequentOperations(t *testing.T) {
92		dir := t.TempDir()
93		s, err := Open(dir)
94		if err != nil {
95			t.Fatal(err)
96		}
97		defer s.Close()
98		reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
99		if err := s.Freeze(FreezeInput{ArchiveID: "A-1", FreezeID: "F-1", Reason: "诉讼", FrozenOn: MustParseDate("2025-01-05")}); err != nil {
100			t.Fatal(err)
101		}
102		if err := s.Release(ReleaseInput{ArchiveID: "A-1", FreezeID: "F-1", Reason: "结案", ReleasedOn: MustParseDate("2025-01-06")}); err != nil {
103			t.Fatal(err)
104		}
105		// 此前查询成功，调用者手里持有正常结果。
106		if _, found, err := s.History("A-1"); err != nil || !found {
107			t.Fatalf("前置查询应成功: found=%v err=%v", found, err)
108		}
109	
110		original := readStateFile(t, dir)
111		// 合法对象后面拼接无法解析的文字：即使前一段能读出档案，整份文件也判为损坏。
112		writeStateFile(t, dir, original+"\n 这不是合法JSON")
113	
114		// 查询不得给出档案不存在、空历史或可以销毁之类的正常结论。
115		if _, found, err := s.History("A-1"); err == nil || found {
116			t.Fatalf("损坏后 History 应失败且不得给出结论: found=%v err=%v", found, err)
117		}
118		if _, found, err := s.GetManifest("APP-1"); err == nil || found {
119			t.Fatalf("损坏后 GetManifest 应失败且不得给出结论: found=%v err=%v", found, err)
120		}
121		if _, err := s.Check(CheckRequest{
122			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
123		}); err == nil {
124			t.Fatal("损坏后 Check 应失败，不得给出可以办理等结论")
125		}
126	
127		// 办理不得新增档案、改动期限、解除冻结或生成清册。
128		if err := s.Register(RegisterInput{ID: "A-2", Category: "凭证", Start: MustParseDate("2020-01-01"), End: MustParseDate("2025-01-10")}); err == nil {
129			t.Fatal("损坏后 Register 应失败")
130		}
131		if err := s.Freeze(FreezeInput{ArchiveID: "A-1", FreezeID: "F-2", Reason: "审计", FrozenOn: MustParseDate("2025-01-07")}); err == nil {
132			t.Fatal("损坏后 Freeze 应失败")
133		}
134		if err := s.Release(ReleaseInput{ArchiveID: "A-1", FreezeID: "F-1", Reason: "结案", ReleasedOn: MustParseDate("2025-01-07")}); err == nil {
135			t.Fatal("损坏后 Release 应失败")
136		}
137		if _, err := s.Revise(ReviseInput{
138			RevisionID: "REV-1", ArchiveID: "A-1",
139			OriginalEnd: MustParseDate("2025-01-10"), NewEnd: MustParseDate("2026-01-10"),
140			RevisedOn: MustParseDate("2025-01-07"), Reason: "延期",
141		}); err == nil {
142			t.Fatal("损坏后 Revise 应失败")
143		}
144		if _, err := s.Destroy(DestructionRequest{
145			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
146		}); err == nil {
147			t.Fatal("损坏后 Destroy 应失败")
148		}
149	
150		// 原文件保持原样：不得自动清空、修补、截去尾部或重新保存。
151		if got := readStateFile(t, dir); got != original+"\n 这不是合法JSON" {
152			t.Fatalf("读取失败后原文件被改动:\n%q", got)
153		}
154	
155		// 恢复合法内容后：失败的销毁申请没有留下清册，申请编号仍可正常使用。
156		writeStateFile(t, dir, original)
157		if _, found, err := s.GetManifest("APP-1"); err != nil || found {
158			t.Fatalf("失败的销毁申请不应留下清册: found=%v err=%v", found, err)
159		}
160		if _, err := s.Destroy(DestructionRequest{
161			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
162		}); err != nil {
163			t.Fatalf("恢复后同一申请编号应能正常办理: %v", err)
164		}
165	}
166	
167	// 引入期限修订之前保存的有效记录（没有 initial_end、revisions 字段）
168	// 不能被当作损坏，最初截止日按登记截止日补齐。
169	func TestOpenLegacyStateWithoutRevisionFields(t *testing.T) {
170		dir := t.TempDir()
171		writeStateFile(t, dir, `{"version":1,"archives":{"A-1":{"id":"A-1","category":"合同","start":"2020-01-01","end":"2025-01-10","destroyed":false,"freezes":[]}},"manifests":{}}`)
172	
173		s, err := Open(dir)
174		if err != nil {
175			t.Fatalf("修订功能之前保存的记录应能打开: %v", err)
176		}
177		defer s.Close()
178		h, found, err := s.History("A-1")
179		if err != nil || !found {
180			t.Fatalf("旧记录应能查询: found=%v err=%v", found, err)
181		}
182		if !h.InitialEnd.Equal(MustParseDate("2025-01-10")) || !h.RetentionEnd.Equal(MustParseDate("2025-01-10")) {
183			t.Fatalf("缺少修订信息时最初截止日应取登记截止日: %+v", h)
184		}
185	}
186	
187	// 已解除冻结缺少解除日期或原因、解除日期早于冻结日期时，
188	// 即使 JSON 本身能解析，Open 也必须按记录损坏处理：返回 ErrCorruptState，
189	// 错误信息能定位到档案与冻结编号，原文件保持原样。
190	func TestOpenRejectsIncompleteReleaseRecords(t *testing.T) {
191		valid := `{"version":1,"archives":{"A-1":{"id":"A-1","category":"合同","start":"2020-01-01","end":"2025-01-10","initial_end":"2025-01-10","freezes":[{"id":"F-1","reason":"诉讼","frozen_on":"2025-01-05","released":true,"release_reason":"结案","released_on":"2025-01-06"}]}},"manifests":{}}`
192		corrupt := map[string]string{
193			"缺解除原因字段":    `{"version":1,"archives":{"A-1":{"id":"A-1","category":"合同","start":"2020-01-01","end":"2025-01-10","initial_end":"2025-01-10","freezes":[{"id":"F-1","reason":"诉讼","frozen_on":"2025-01-05","released":true,"released_on":"2025-01-06"}]}},"manifests":{}}`,
194			"解除原因只有空白":   `{"version":1,"archives":{"A-1":{"id":"A-1","category":"合同","start":"2020-01-01","end":"2025-01-10","initial_end":"2025-01-10","freezes":[{"id":"F-1","reason":"诉讼","frozen_on":"2025-01-05","released":true,"release_reason":"  \t ","released_on":"2025-01-06"}]}},"manifests":{}}`,
195			"解除原因为空串":    `{"version":1,"archives":{"A-1":{"id":"A-1","category":"合同","start":"2020-01-01","end":"2025-01-10","initial_end":"2025-01-10","freezes":[{"id":"F-1","reason":"诉讼","frozen_on":"2025-01-05","released":true,"release_reason":"","released_on":"2025-01-06"}]}},"manifests":{}}`,
196			"缺解除日期字段":    `{"version":1,"archives":{"A-1":{"id":"A-1","category":"合同","start":"2020-01-01","end":"2025-01-10","initial_end":"2025-01-10","freezes":[{"id":"F-1","reason":"诉讼","frozen_on":"2025-01-05","released":true,"release_reason":"结案"}]}},"manifests":{}}`,
197			"解除日期为 null": `{"version":1,"archives":{"A-1":{"id":"A-1","category":"合同","start":"2020-01-01","end":"2025-01-10","initial_end":"2025-01-10","freezes":[{"id":"F-1","reason":"诉讼","frozen_on":"2025-01-05","released":true,"release_reason":"结案","released_on":null}]}},"manifests":{}}`,
198			"解除日期早于冻结日期": `{"version":1,"archives":{"A-1":{"id":"A-1","category":"合同","start":"2020-01-01","end":"2025-01-10","initial_end":"2025-01-10","freezes":[{"id":"F-1","reason":"诉讼","frozen_on":"2025-01-05","released":true,"release_reason":"结案","released_on":"2025-01-04"}]}},"manifests":{}}`,
199		}
200		for name, content := range corrupt {
201			t.Run(name, func(t *testing.T) {
202				dir := t.TempDir()
203				writeStateFile(t, dir, content)
204	
205				s, err := Open(dir)
206				if err == nil {
207					s.Close()
208					t.Fatal("解除记录不完整时不应打开成功")
209				}
210				if !errors.Is(err, ErrCorruptState) {
211					t.Fatalf("错误应可判定为 ErrCorruptState，得到 %v", err)
212				}
213				msg := err.Error()
214				if !strings.Contains(msg, "A-1") || !strings.Contains(msg, "F-1") {
215					t.Fatalf("错误信息应指出档案与冻结编号，得到 %v", err)
216				}
217				if got := readStateFile(t, dir); got != content {
218					t.Fatalf("打开失败后原文件被改动: %q -> %q", content, got)
219				}
220			})
221		}
222	
223		// 对照组：内容完整的已解除记录（含旧格式缺 initial_end）必须能正常打开，
224		// 防止把合法记录误判成损坏。
225		t.Run("完整解除记录可打开", func(t *testing.T) {
226			dir := t.TempDir()
227			writeStateFile(t, dir, valid)
228			s, err := Open(dir)
229			if err != nil {
230				t.Fatalf("完整的解除记录应能打开: %v", err)
231			}
232			defer s.Close()
233		})
234		t.Run("旧格式记录中的完整解除可打开", func(t *testing.T) {
235			legacy := `{"version":1,"archives":{"A-1":{"id":"A-1","category":"合同","start":"2020-01-01","end":"2025-01-10","freezes":[{"id":"F-1","reason":"诉讼","frozen_on":"2025-01-05","released":true,"release_reason":"结案","released_on":"2025-01-06"}]}},"manifests":{}}`
236			dir := t.TempDir()
237			writeStateFile(t, dir, legacy)
238			s, err := Open(dir)
239			if err != nil {
240				t.Fatalf("旧格式但解除信息完整的记录应能打开: %v", err)
241			}
242			defer s.Close()
243		})
244	}
245	
246	// 未解除冻结没有解除日期和原因是合法状态，仍要继续阻止销毁；
247	// 已解除冻结的解除日期与冻结日期相同也合法，历史保留完整信息且不再阻碍。
248	func TestValidFreezeRecordsKeepWorking(t *testing.T) {
249		t.Run("未解除冻结合法且阻止销毁", func(t *testing.T) {
250			dir := t.TempDir()
251			s, err := Open(dir)
252			if err != nil {
253				t.Fatal(err)
254			}
255			defer s.Close()
256			reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
257			if err := s.Freeze(FreezeInput{ArchiveID: "A-1", FreezeID: "F-1", Reason: "诉讼", FrozenOn: MustParseDate("2025-01-05")}); err != nil {
258				t.Fatal(err)
259			}
260			r, err := s.Check(CheckRequest{
261				ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
262			})
263			if err != nil {
264				t.Fatalf("未解除冻结是合法记录，核对不应报错: %v", err)
265			}
266			if r.Status != CheckBlocked || len(r.Results[0].Obstructions) != 1 ||
267				r.Results[0].Obstructions[0].Kind != ObstructionActiveFreeze {
268				t.Fatalf("未解除冻结应给出一条冻结阻碍: %+v", r)
269			}
270			if _, err := s.Destroy(DestructionRequest{
271				ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
272			}); !errors.Is(err, ErrActiveFreeze) {
273				t.Fatalf("未解除冻结应阻止销毁，得到 %v", err)
274			}
275		})
276	
277		t.Run("解除日期与冻结日期相同合法", func(t *testing.T) {
278			dir := t.TempDir()
279			s, err := Open(dir)
280			if err != nil {
281				t.Fatal(err)
282			}
283			defer s.Close()
284			reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
285			if err := s.Freeze(FreezeInput{ArchiveID: "A-1", FreezeID: "F-1", Reason: "诉讼", FrozenOn: MustParseDate("2025-01-05")}); err != nil {
286				t.Fatal(err)
287			}
288			if err := s.Release(ReleaseInput{ArchiveID: "A-1", FreezeID: "F-1", Reason: "结案", ReleasedOn: MustParseDate("2025-01-05")}); err != nil {
289				t.Fatalf("解除日期与冻结日期相同应合法: %v", err)
290			}
291			h, found, err := s.History("A-1")
292			if err != nil || !found {
293				t.Fatalf("历史查询失败: found=%v err=%v", found, err)
294			}
295			if len(h.Freezes) != 1 || !h.Freezes[0].Released ||
296				h.Freezes[0].ReleaseReason != "结案" ||
297				!h.Freezes[0].ReleasedOn.Equal(MustParseDate("2025-01-05")) ||
298				len(h.ActiveFreezes) != 0 {
299				t.Fatalf("历史应保留完整解除信息且不再算作未解除: %+v", h.Freezes)
300			}
301			r, err := s.Check(CheckRequest{
302				ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
303			})
304			if err != nil {
305				t.Fatalf("核对不应报错: %v", err)
306			}
307			if r.Status != CheckReady {
308				t.Fatalf("已解除冻结不应阻碍销毁: %+v", r)
309			}
310			if _, err := s.Destroy(DestructionRequest{
311				ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
312			}); err != nil {
313				t.Fatalf("到期且无未解除冻结时应能销毁: %v", err)
314			}
315		})
316	}
317	
318	// rewriteState 解析已保存状态、按 fn 修改后原样写回（保持 JSON 合法），
319	// 用于模拟保管库打开之后保存内容被改成语义损坏的记录。
320	func rewriteState(t *testing.T, dir string, fn func(map[string]any)) {
321		t.Helper()
322		path := filepath.Join(dir, stateFileName)
323		raw, err := os.ReadFile(path)
324		if err != nil {
325			t.Fatal(err)
326		}
327		var doc map[string]any
328		if err := json.Unmarshal(raw, &doc); err != nil {
329			t.Fatal(err)
330		}
331		fn(doc)
332		out, err := json.MarshalIndent(doc, "", "  ")
333		if err != nil {
334			t.Fatal(err)
335		}
336		if err := os.WriteFile(path, out, 0o600); err != nil {
337			t.Fatal(err)
338		}
339	}
340	
341	// 保管库打开后保存内容才出现不完整解除记录：下一次使用有效输入的
342	// 历史查询、清册查询、销毁前核对与正式销毁都必须返回 ErrCorruptState，
343	// 不能把档案说成不存在、不能给出可以办理或部分报告、不能生成清册，
344	// 且失败后原保存内容保持原样。
345	func TestIncompleteReleaseAfterOpenFailsAllOperations(t *testing.T) {
346		dir := t.TempDir()
347		s, err := Open(dir)
348		if err != nil {
349			t.Fatal(err)
350		}
351		defer s.Close()
352		reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
353		if err := s.Freeze(FreezeInput{ArchiveID: "A-1", FreezeID: "F-1", Reason: "诉讼", FrozenOn: MustParseDate("2025-01-05")}); err != nil {
354			t.Fatal(err)
355		}
356		if err := s.Release(ReleaseInput{ArchiveID: "A-1", FreezeID: "F-1", Reason: "结案", ReleasedOn: MustParseDate("2025-01-06")}); err != nil {
357			t.Fatal(err)
358		}
359		if _, found, err := s.History("A-1"); err != nil || !found {
360			t.Fatalf("损坏前查询应成功: found=%v err=%v", found, err)
361		}
362	
363		// 把解除原因改空：只剩“已解除”标记。
364		rewriteState(t, dir, func(doc map[string]any) {
365			freezes := doc["archives"].(map[string]any)["A-1"].(map[string]any)["freezes"].([]any)
366			freezes[0].(map[string]any)["release_reason"] = "   "
367		})
368		corruptContent := readStateFile(t, dir)
369	
370		if h, found, err := s.History("A-1"); !errors.Is(err, ErrCorruptState) || found || h.ID != "" {
371			t.Fatalf("损坏后 History 必须返回 ErrCorruptState 且无结论: found=%v err=%v", found, err)
372		}
373		if _, found, err := s.GetManifest("APP-1"); !errors.Is(err, ErrCorruptState) || found {
374			t.Fatalf("损坏后 GetManifest 必须返回 ErrCorruptState: found=%v err=%v", found, err)
375		}
376		if r, err := s.Check(CheckRequest{
377			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
378		}); !errors.Is(err, ErrCorruptState) || r.Status != "" || len(r.Results) != 0 {
379			t.Fatalf("损坏后 Check 必须失败且不得给出部分报告: %+v err=%v", r, err)
380		}
381		if m, err := s.Destroy(DestructionRequest{
382			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
383		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
384			t.Fatalf("损坏后 Destroy 必须失败且不得生成清册: %+v err=%v", m, err)
385		}
386		if err := s.Register(RegisterInput{ID: "A-2", Category: "凭证", Start: MustParseDate("2020-01-01"), End: MustParseDate("2025-01-10")}); !errors.Is(err, ErrCorruptState) {
387			t.Fatalf("损坏后 Register 必须失败: %v", err)
388		}
389		if err := s.Freeze(FreezeInput{ArchiveID: "A-1", FreezeID: "F-2", Reason: "审计", FrozenOn: MustParseDate("2025-01-07")}); !errors.Is(err, ErrCorruptState) {
390			t.Fatalf("损坏后 Freeze 必须失败: %v", err)
391		}
392	
393		// 失败不得触发重新保存：损坏内容原样保留，不补原因、不删冻结。
394		if got := readStateFile(t, dir); got != corruptContent {
395			t.Fatalf("失败后原保存内容被改动:\n%q", got)
396		}
397	}
398	
399	// 损坏判断适用于库内全部已解除冻结，与本次办理名单无关：
400	// 异常记录挂在另一份已经销毁的档案下时，查询、核对、销毁其他档案
401	// 同样必须按记录损坏失败，不能把不完整解除信息作为正常历史返回。
402	func TestCorruptReleaseOnDestroyedArchiveFailsWholeVault(t *testing.T) {
403		dir := t.TempDir()
404		s, err := Open(dir)
405		if err != nil {
406			t.Fatal(err)
407		}
408		defer s.Close()
409		reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
410		reg(t, s, "D-1", "凭证", "2020-01-01", "2025-01-10")
411		if err := s.Freeze(FreezeInput{ArchiveID: "D-1", FreezeID: "F-D", Reason: "协查", FrozenOn: MustParseDate("2025-01-05")}); err != nil {
412			t.Fatal(err)
413		}
414		if err := s.Release(ReleaseInput{ArchiveID: "D-1", FreezeID: "F-D", Reason: "协查结束", ReleasedOn: MustParseDate("2025-01-06")}); err != nil {
415			t.Fatal(err)
416		}
417		if _, err := s.Destroy(DestructionRequest{
418			ApplicationID: "APP-D", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"D-1"},
419		}); err != nil {
420			t.Fatal(err)
421		}
422	
423		// 损坏发生在已销毁档案 D-1 身上（去掉解除日期）。
424		rewriteState(t, dir, func(doc map[string]any) {
425			freezes := doc["archives"].(map[string]any)["D-1"].(map[string]any)["freezes"].([]any)
426			delete(freezes[0].(map[string]any), "released_on")
427		})
428		corruptContent := readStateFile(t, dir)
429	
430		// 重新打开整个位置必须失败，错误指出 D-1 与 F-D。
431		s2, err := Open(dir)
432		if err == nil {
433			s2.Close()
434			t.Fatal("库内任一已解除冻结不完整时，打开必须失败")
435		}
436		if !errors.Is(err, ErrCorruptState) || !strings.Contains(err.Error(), "D-1") || !strings.Contains(err.Error(), "F-D") {
437			t.Fatalf("打开错误应为 ErrCorruptState 并指出 D-1/F-D，得到 %v", err)
438		}
439	
440		// 已打开的实例：即使本次只查询、核对、销毁与异常记录无关的 A-1，
441		// 也必须按整库损坏失败。
442		if _, found, err := s.History("A-1"); !errors.Is(err, ErrCorruptState) || found {
443			t.Fatalf("查询无关档案 A-1 也应返回 ErrCorruptState: found=%v err=%v", found, err)
444		}
445		if _, found, err := s.History("D-1"); !errors.Is(err, ErrCorruptState) || found {
446			t.Fatalf("查询已销毁的异常档案不得返回（不完整的）历史: found=%v err=%v", found, err)
447		}
448		if _, found, err := s.GetManifest("APP-D"); !errors.Is(err, ErrCorruptState) || found {
449			t.Fatalf("查询异常档案所属清册也应失败: found=%v err=%v", found, err)
450		}
451		if r, err := s.Check(CheckRequest{
452			ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
453		}); !errors.Is(err, ErrCorruptState) || r.Status != "" {
454			t.Fatalf("核对无关档案也应整次失败: %+v err=%v", r, err)
455		}
456		if m, err := s.Destroy(DestructionRequest{
457			ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
458		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
459			t.Fatalf("不得在损坏状态下生成清册: %+v err=%v", m, err)
460		}
461		if got := readStateFile(t, dir); got != corruptContent {
462			t.Fatalf("失败后原保存内容被改动:\n%q", got)
463		}
464	}
